INSERT INTO journeys (id,name,target_persona,description) VALUES ('J13','Visa & pháp lý dài hạn','P1','Đăng ký lưu trú, gia hạn, mất giấy tờ, chuyển trường, làm thêm hợp pháp, tốt nghiệp và rời khỏi Trung Quốc');
INSERT INTO journeys (id,name,target_persona,description) VALUES ('J14','Liên lạc với gia đình ở xa','P1','Duy trì liên lạc, báo bình an, chuyển tiền, chia sẻ đời sống, xử lý khẩn cấp và lên kế hoạch dài hạn cùng gia đình');
